  origin: 'https://your-trusted-frontend.com', // Replace with your actual domain or '*' for public APIs
  methods: ['GET', 'POST', 'PUT', 'DELETE']
}));

// Parse incoming JSON payloads (required for POST/PUT requests)
// Limit the body size to prevent payload-too-large DoS attacks
app.use(express.json({ limit: '10kb' })); 

// Apply Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per `window` (here, per 15 minutes)
  message: { error: 'Too many requests from this IP, please try again later.' },
