    return res.status(400).json({ error: 'Invalid user ID format. Must be a positive integer.' });
  }

  // ... fetch user logic ...
  res.json({ id: userId, name: 'Test User' });
});


// --- 3. Error Handling ---

// Handle 404 - Route Not Found
app.use((req, res, next) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global Error Handling Middleware
// Catches any errors thrown in routes and prevents stack trace leaks
app.use((err, req, res, next) => {
  console.error(`[Error] ${err.message}`); // Log internally for debugging

